<?php
$labels = ['new' => 'Novas OS', 'absent' => 'Não presentes no snapshot atual', 'completed' => 'Passaram para fechada', 'open' => 'Passaram para em aberto', 'cancelled' => 'Passaram para cancelada'];
$this->assign('title', $labels[$type]);
?>
<header class="pcm-page-header"><div><p class="pcm-eyebrow">PCM | MOVIMENTAÇÃO</p><h1><?= h($labels[$type]) ?></h1><p class="pcm-updated"><?= $area ? 'Setor: ' . h($area->display_name) . ' • ' : '' ?>Comparação entre os dois últimos relatórios reais</p></div><div><?= $this->Html->link('Voltar', $area ? ['_name' => 'pcm-sector', 'code' => $area->source_code] : ['_name' => 'pcm'], ['class' => 'btn btn-outline-secondary']) ?></div></header>
<?php if ($type === 'absent'): ?><div class="alert alert-light border">Estas OS são classificadas apenas como <strong>não presentes no snapshot atual</strong>. Ausência não significa conclusão.</div><?php endif; ?>
<div class="pcm-panel"><div class="table-responsive"><table class="table pcm-orders-table align-middle mb-0"><thead><tr><th>Ordem Serv.</th><th>Bem</th><th>Nome do Bem</th><th>Serviço</th><th>Área</th><th>STATUS anterior</th><th>STATUS observado</th><th></th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><strong><?= h($order->source_order_number) ?></strong></td><td><?= h($order->equipment_code ?: '—') ?></td><td><?= h($order->equipment_name ?: '—') ?></td><td><?= h($order->service_name ?: '—') ?></td><td><?= h($order->maintenance_area_code ?: '—') ?></td><td><?= h($order->previous_status ?: '—') ?></td><td><?= h($type === 'absent' ? 'Não presente' : $order->treated_status) ?></td><td><?php if ($type !== 'absent'): ?><?= $this->Html->link('Ver detalhes', ['_name' => 'pcm-order', 'id' => $order->id], ['class' => 'btn btn-sm btn-outline-primary']) ?><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if (count($orders) === 0): ?><tr><td colspan="8" class="pcm-empty-table">Nenhuma OS nesta movimentação.</td></tr><?php endif; ?></tbody></table></div><?php if (count($orders) > 0): ?><footer class="pcm-pagination"><p><?= $this->Paginator->counter('Página {{page}} de {{pages}} • {{count}} OS') ?></p><nav aria-label="Paginação"><ul class="pcm-page-list"><?= $this->Paginator->prev('‹ Anterior') ?><?= $this->Paginator->numbers(['modulus' => 5, 'first' => 1, 'last' => 1]) ?><?= $this->Paginator->next('Próxima ›') ?></ul></nav></footer><?php endif; ?></div>
